/// <summary>
/// PricingAttribute of table <c>CustDirectDebitMandate</c> field ExpirationDate.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustDirectDebitMandateExpirationDate extends UPSPricingAttributeCustDirectDebitMandate implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustDirectDebitMandate, ExpirationDate);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::Date);
    CustDirectDebitMandate custDirectDebitMandate;

    while select custDirectDebitMandate
        group by ExpirationDate
    {
        if (! ret.in(custDirectDebitMandate.ExpirationDate))
        {
            ret.add(custDirectDebitMandate.ExpirationDate);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, ExpirationDate));
    qbr.value(queryValue(_value));
}
